# owner: platform
"""Contact sheet for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student

def _sort_key(student: Student) -> tuple:
    return (student.display_name.casefold(), student.student_id)

def _require_contacts(people: List[Student]) -> None:
    if not people:
        raise ValueError("no students to list")
    for person in people:
        if not person.email:
            raise ValueError(f"no email for {person.display_name}")

def _widest(values: Iterable[str]) -> int:
    return max(len(value) for value in values)

def _layout(people: List[Student]) -> str:
    name_wide = _widest(item.display_name for item in people)
    sect_wide = _widest(item.section for item in people)
    return f"{{name:<{name_wide}}}  {{sect:<{sect_wide}}}  {{mail}}"

def _row(layout: str, item: Student) -> str:
    return layout.format(name=item.display_name, sect=item.section, mail=item.email)

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by name."""
    people = sorted(students, key=_sort_key)
    _require_contacts(people)
    layout = _layout(people)
    return [_row(layout, item) for item in people]
